#include <iostream>
#include <string>
#include <stdexcept>
using namespace std;

int main() {
    string word;
    int pos = 0;
    getline(cin, word);
    cin >> pos;

    try {
        char c = word.at(pos);
        cout << "第 " << pos << " 号位是 " << c << " " << endl;
    } catch (const out_of_range& e) {
        cout << "越界：" << "索引超出范围" << endl;
    }
    return 0;
}
